// signed 32-bit hash (can be negative), like Java's String.hashCode
function signedHash(s){let h=0;for(let i=0;i<s.length;i++){h=(Math.imul(31,h)+s.charCodeAt(i))|0;}return h;}

function shardFor(key, N) {
  return signedHash(key) % N;   // BUG: negative hash -> negative index
}

