const SHARDS = [db0, db1, db2, db3];

// route a tenant-scoped query to its shard
function routeQuery(filters, sql) {
  const key = filters.email || filters.tenantId;   // shard key
  const shard = SHARDS[hash(key) % SHARDS.length];
  return shard.query(sql, filters);
}

